import math

def build_instance(rng):
    coefficient_1 = rng.randint(1, 10)
    coefficient_2 = rng.randint(1, 10)
    while math.gcd(coefficient_1, coefficient_2) != 1:
        coefficient_1 = rng.randint(1, 10)
        coefficient_2 = rng.randint(1, 10)
    constant_term = rng.randint(-10, 10)
    answer = abs(constant_term) // math.gcd(coefficient_1, coefficient_2)
    check = 0
    for x in range(-10, 11):
        for y in range(-10, 11):
            if coefficient_1 * x + coefficient_2 * y == constant_term:
                check += 1
    parameters = {'coefficient_1': coefficient_1, 'coefficient_2': coefficient_2, 'constant_term': constant_term}
    return (parameters, answer, check)



