    quadratic_coefficient = rng.randint(1, 10)
    linear_coefficient = rng.randint(-10, 10)
    constant_term = rng.randint(-10, 10)
    left_endpoint = rng.randint(-10, -2)
    right_endpoint = rng.randint(2, 10)
    x = sympy.symbols('x')
    f = quadratic_coefficient * x ** 2 + linear_coefficient * x + constant_term
    integral = sympy.integrate(f, (x, left_endpoint, right_endpoint))
    answer = 'Yes' if integral >= 0 else 'No'
    check = 'Yes' if quadratic_coefficient * (right_endpoint ** 3 - left_endpoint ** 3) / 3 + linear_coefficient * (right_endpoint ** 2 - left_endpoint ** 2) / 2 + constant_term * (right_endpoint - left_endpoint) >= 0 else 'No'
