        roots = sympy.solve(quadratic_expr, x)
        root1, root2 = roots
        if root1.is_integer and root2.is_integer:
            # Both roots are integers
            if root1 <= root2:
                answer = max_x - root1 + 1 if root1 >= 0 else max_x - root2 + 1
            else:
                answer = max_x - root2 + 1 if root2 >= 0 else max_x - root1 + 1
        else:
