    check = sum(1 for x in range(1, max_x + 1) if x**2 - quadratic_coefficient * x + constant_term >= 0)
    parameters = {"max_x": max_x, "quadratic_coefficient": quadratic_coefficient, "constant_term": constant_term}
    return parameters, answer, check
